pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed actor: caller address that will call NETM().
    // General rule: after NETM() is called by the owner, balances[owner] == totalDistributed.
    // The mutant that fails to assign owner = msg.sender inside NETM() will violate this for some inputs
    // when NETM is called by the current owner (which may differ depending on previous ownership transfers).
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses reasonable (non-zero)
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // initial deployer is owner (set in constructor as msg.sender). That is this test contract.
        // But the contract C sets owner = msg.sender in its top-level declaration, so owner is address(this) at deployment.
        // We'll transfer ownership to `caller` so that `caller` becomes the owner then call NETM() as caller.

        // transfer ownership to caller using the public transferOwnership (onlyOwner) from this test contract
        c.transferOwnership(caller);

        // Now simulate caller calling NETM(). We must make the call as caller.
        vm.prank(caller);
        // NETM is public onlyOwner, so this should succeed.
        c.NETM();

        // The general property (reference): balances[caller] == totalDistributed after caller calls NETM.
        // We read totalDistributed via the public getter (public variable) and balances via balanceOf.
        uint256 bal = c.balanceOf(caller);
        uint256 td = c.totalDistributed();

        assertTrue(bal == td);
    }
}

