pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: the caller who will invoke NETM().
    // The property: after any address caller calls NETM(), balances[caller] equals totalDistributed.
    // The buggy mutant (which does not set owner = msg.sender) can leave balances set on a different owner,
    // so for some caller addresses the invariant will be violated.
    function testFuzz_property(address caller) public {
        // avoid zero address to keep domain wide but meaningful
        vm.assume(caller != address(0));

        // fund caller so calls that might be payable or rely on balance do not fail
        vm.deal(caller, 1 ether);

        // impersonate caller and call NETM()
        vm.prank(caller);
        // NETM is non-payable and onlyOwner; when deployed, constructor set owner = deployer (setUp's sender = this test),
        // so only that owner can call NETM() in both reference and mutant. To satisfy onlyOwner, we must call as the original owner.
        // Therefore, we instead arrange to call NETM() as the original owner to exercise the code path while still
        // observing the property that reference sets balances[caller] == totalDistributed when caller == owner.
        // To let the fuzzer vary which address is observed, we will first transfer ownership to the fuzzed caller,
        // then call NETM() as that owner. TransferOwnership onlyOwner, so we must perform it from initial owner.

        // compute current owner (the deployer test contract created c, so owner is address(this) at c construction)
        address initialOwner = address(this);

        // transfer ownership from initialOwner to caller by calling transferOwnership as initialOwner
        // since setUp() created c via new C(), the test contract is the deployer/owner; call directly
        c.transferOwnership(caller);

        // now call NETM() as the new owner (caller)
        vm.prank(caller);
        // wrap call to capture reverts in either version
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract: after NETM() (called by owner), balances[caller] == totalDistributed and call does not revert.
        // We assert that if the call succeeded, the balances[caller] equals totalDistributed; if call reverted, the reference
        // would also revert for same inputs, but mutant may behave differently. To keep a universal property that holds for
        // all inputs on the reference, we assert that either the call reverted (ok == false) OR balances[caller] == totalDistributed.
        // This single assert is satisfied by the reference for all callers, but the mutant (which fails to set owner = msg.sender)
        // will for some caller produce ok == true but balances[caller] != totalDistributed, failing the assertion.

        uint256 bal = c.balanceOf(caller);
        uint256 td = c.totalDistributed();

        assertTrue(!ok || bal == td);
    }
}

