pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address to find one that distinguishes the mutant
    function testFuzz_property(address caller) public {
        // admissible domain: avoid zero address because many contracts treat it specially
        vm.assume(caller != address(0));

        // Fund the caller so it can make any payable calls if needed (not strictly required here)
        vm.deal(caller, 1 ether);

        // Call NETM as the fuzzed caller
        vm.prank(caller);
        // Use try/catch to ensure we capture revert behavior; NETM is non-payable and should not revert for valid caller
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference behavior: NETM sets owner = msg.sender and then sets balances[owner] = totalDistributed.
        // Therefore after NETM returns (or even if it reverts, but it shouldn't), for the correct contract the caller's
        // balances[caller] must equal c.totalDistributed() if the call succeeded. We assert that when the call
        // succeeded, balances[caller] == totalDistributed.
        if (ok) {
            assertTrue(c.balanceOf(caller) == c.totalDistributed());
        } else {
            // If NETM reverted, still assert false because reference should not revert for a non-zero caller
            // but to keep the property universal over admissible inputs, require that NETM does not revert.
            // This makes the single assertion below equivalent: ok must be true.
            assertTrue(false);
        }
    }
}
